import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def blocks(g):
    H,W=len(g),len(g[0])
    rb=[i for i in range(H) if all(x==6 for x in g[i])]
    cb=[j for j in range(W) if all(g[i][j]==6 for i in range(H))]
    def segs(sz,seps):
        out=[];s=0
        for e in seps+[sz]:
            if e>s: out.append((s,e))
            s=e+1
        return out
    return segs(H,rb), segs(W,cb)

def transform(grid):
    bg=grid[0][0]
    rsegs,csegs=blocks(grid)
    out=[]
    for r0,r1 in rsegs:
        row=[]
        for c0,c1 in csegs:
            n=sum(1 for i in range(r0,r1) for j in range(c0,c1) if grid[i][j] not in (6,bg))
            row.append(1 if n>=2 else 3)
        out.append(row)
    return out

demo_in=G['Demo pair 1 input']; demo_out=G['Demo pair 1 output']
r=transform(demo_in)
print(r==demo_out, r, demo_out)
import json
test=transform(G['Test input'])
